<?php $c=$collaboration;$taskId=(int)$task['id'];$taskVersion=(int)$task['version'];$count=count($c['items']);$percent=$count?(int)round($c['checked']*100/$count):0; ?>
<?php if($task['parent_id']!==null): ?>
<section class="crm-card client-panel"><h2>Parent task</h2><?php if($c['parent']): ?><a class="subtle-link" href="<?= site_url('tasks/'.$c['parent']['id']) ?>"><?= esc($c['parent']['title']) ?></a><?php else: ?><p class="text-secondary">Parent task details require independent access.</p><?php endif ?><p class="text-secondary mt-2 mb-0">Subtasks use their own assignment, status and completion. One level of subtasks is supported.</p></section>
<?php else:$children=$c['children']; ?>
<section class="crm-card client-panel" id="task-subtasks"><div class="client-section-heading"><h2>Subtasks</h2><?php if($c['canCreateSubtask']): ?><a class="subtle-link" href="<?= site_url('tasks/new?parent='.$taskId) ?>">+ Create subtask</a><?php endif ?></div>
<p class="text-secondary">Only independently authorized subtasks are shown. Completing a subtask does not complete this task.</p>
<div class="client-actions mb-3"><a class="subtle-link" href="<?= site_url('tasks/'.$taskId.'?subtasks_archive=active#task-subtasks') ?>">Unarchived</a><a class="subtle-link" href="<?= site_url('tasks/'.$taskId.'?subtasks_archive=archived#task-subtasks') ?>">Archived</a></div>
<?php foreach($children['rows'] as $child): ?><article class="client-entry"><h3><a class="subtle-link" href="<?= site_url('tasks/'.$child['id']) ?>"><?= esc($child['title']) ?></a></h3><p><?= esc($child['code']) ?> · <?= esc($child['assignee_name']?:'Unassigned') ?></p><span class="state-pill <?= $child['category']==='done'?'teal':'violet' ?>"><?= esc($child['status_name']) ?></span></article><?php endforeach ?>
<?php if(!$children['rows']): ?><p class="text-secondary">No authorized subtasks match this view.</p><?php endif ?>
<nav class="client-pagination" aria-label="Subtasks pagination"><span>Page <?= (int)$children['page'] ?> of <?= (int)$children['pages'] ?></span><div><?php foreach([-1=>'Previous',1=>'Next'] as $offset=>$label):$next=$children['page']+$offset;if($next<1||$next>$children['pages'])continue; ?><a class="subtle-link" href="<?= esc(site_url('tasks/'.$taskId).'?'.http_build_query(['subtasks_page'=>$next,'subtasks_archive'=>$children['archive']]).'#task-subtasks') ?>"><?= $label ?></a><?php endforeach ?></div></nav></section>
<?php endif ?>
<section class="crm-card client-panel" id="task-checklist"><h2>Checklist</h2><p class="text-secondary" id="checklist-progress-text"><?= (int)$c['checked'] ?> of <?= $count ?> items completed</p>
<div class="progress mb-3" role="progressbar" aria-label="Completed checklist items" aria-valuemin="0" aria-valuemax="<?= max(1,$count) ?>" aria-valuenow="<?= (int)$c['checked'] ?>"><div class="progress-bar bg-success" style="width:<?= $percent ?>%"></div></div>
<?php foreach($c['items'] as $index=>$item):$itemId=(int)$item['id']; ?>
<article class="client-entry checklist-entry" data-checklist-item="<?= $itemId ?>"><h3><?= esc($item['label']) ?></h3><span class="state-pill <?= $item['checked_at']?'teal':'violet' ?>"><?= $item['checked_at']?'Completed':'Incomplete' ?></span>
<?php if($c['canChecklist']): ?>
<div class="client-actions mt-3"><form method="post" action="<?= site_url('tasks/'.$taskId.'/checklist/'.$itemId.'/toggle') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= $taskVersion ?>"><button class="btn btn-outline-light" type="submit" name="completed" value="<?= $item['checked_at']?'0':'1' ?>"><?= $item['checked_at']?'Mark incomplete':'Mark complete' ?></button></form>
<?php foreach(['up'=>'Up','down'=>'Down'] as $direction=>$label):if(($direction==='up'&&$index===0)||($direction==='down'&&$index===$count-1))continue; ?><form method="post" action="<?= site_url('tasks/'.$taskId.'/checklist/'.$itemId.'/move') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= $taskVersion ?>"><button class="btn btn-outline-light" name="direction" value="<?= $direction ?>" type="submit" aria-label="Move <?= esc($item['label']) ?> <?= $direction ?>"><?= $label ?></button></form><?php endforeach ?></div>
<details class="mt-3"><summary>Edit item</summary><form method="post" class="mt-3" action="<?= site_url('tasks/'.$taskId.'/checklist/'.$itemId) ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= $taskVersion ?>"><label for="checklist-edit-<?= $itemId ?>">Item text</label><input class="form-control mt-2" id="checklist-edit-<?= $itemId ?>" name="label" value="<?= esc($item['label']) ?>" maxlength="240" required><button class="btn btn-teal mt-3" type="submit">Save item</button></form></details>
<details class="client-remove"><summary>Archive item</summary><form method="post" action="<?= site_url('tasks/'.$taskId.'/checklist/'.$itemId.'/archive') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= $taskVersion ?>"><p>Archive this item and remove it from completion progress?</p><button class="btn btn-outline-warning" type="submit">Confirm archive</button></form></details>
<?php endif ?></article><?php endforeach ?>
<?php if(!$c['items']): ?><p class="text-secondary">No checklist items yet.</p><?php endif ?>
<?php if($c['canChecklist']&&$count<100): ?><form method="post" class="mt-4" action="<?= site_url('tasks/'.$taskId.'/checklist') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= $taskVersion ?>"><label for="checklist-label">New checklist item</label><input class="form-control mt-2" id="checklist-label" name="label" maxlength="240" required><button class="btn btn-teal mt-3" type="submit">Add item</button></form><?php endif ?>
<p class="text-secondary mt-3 mb-0">Up to 100 active items. Ordering is saved. Checklist completion does not change task status.</p></section>
<section class="crm-card client-panel" id="task-comments"><h2>Comments</h2><p class="text-secondary">Visible comments in chronological order, 20 per page. Text is shared with authorized task viewers.</p>
<?php foreach($c['comments'] as $comment):$commentId=(int)$comment['id']; ?>
<article class="client-entry task-comment" data-comment="<?= $commentId ?>"><h3><?= esc($comment['author_name']) ?></h3><p><?= esc($comment['created_at']) ?><?= $comment['edited_at']?' · Edited '.esc($comment['edited_at']):'' ?></p><p class="client-notes"><?= esc($comment['body']) ?></p>
<?php if($comment['can_edit']): ?><details class="mt-3"><summary>Edit your comment</summary><form method="post" class="mt-3" action="<?= site_url('tasks/'.$taskId.'/comments/'.$commentId) ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= $taskVersion ?>"><label for="comment-edit-<?= $commentId ?>">Comment text</label><textarea class="form-control mt-2" id="comment-edit-<?= $commentId ?>" name="body" rows="4" maxlength="5000" required><?= esc($comment['body']) ?></textarea><button class="btn btn-teal mt-3" type="submit">Save comment</button></form></details><?php endif ?>
<?php if($comment['can_hide']): ?><details class="client-remove"><summary>Hide comment</summary><form method="post" action="<?= site_url('tasks/'.$taskId.'/comments/'.$commentId.'/hide') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= $taskVersion ?>"><p>Hide this comment from task viewers? Its text is retained privately for audit.</p><button class="btn btn-outline-warning" type="submit">Confirm hide</button></form></details><?php endif ?></article><?php endforeach ?>
<?php if(!$c['comments']): ?><p class="text-secondary">No visible comments yet.</p><?php endif ?>
<nav class="client-pagination" aria-label="Comments pagination"><span>Page <?= (int)$c['commentsPage'] ?> of <?= (int)$c['commentsPages'] ?></span><div><?php foreach([-1=>'Previous',1=>'Next'] as $offset=>$label):$next=$c['commentsPage']+$offset;if($next<1||$next>$c['commentsPages'])continue; ?><a class="subtle-link" href="<?= site_url('tasks/'.$taskId.'?comments_page='.$next.'#task-comments') ?>"><?= $label ?></a><?php endforeach ?></div></nav>
<?php if($c['canComment']): ?><form method="post" class="mt-4" action="<?= site_url('tasks/'.$taskId.'/comments') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= $taskVersion ?>"><label for="comment-body">New comment</label><textarea class="form-control mt-2" id="comment-body" name="body" rows="4" maxlength="5000" required></textarea><button class="btn btn-teal mt-3" type="submit">Add comment</button></form><?php endif ?>
</section>
